import type { BossConfigData } from "../Config/BossConfig";
import { EmitterRuntime } from "./EmitterRuntime";
import { Plane } from "./Plane";
import type { TurretData } from "./TurretData";
import type { TurretScheduleState } from "./TurretSchedule";

export class Boss extends Plane {
    
    public config: BossConfigData;

    /** 当前阶段索引。0 = 初始阶段 */
    public stageIndex = 0;

    /** 炮台运行时数据。每个 Boss 实例独立 */
    public turrets: TurretData[] = [];

    public turretSchedule: TurretScheduleState | null = null;

    constructor(config: BossConfigData) {
        super('boss');
        this.config = config;
        this.hp = config.maxHp;
        this.maxHp = config.maxHp;
        this.collisionRadius = config.collisionRadius;
        this.enterStage(0);  
    }

     /**
     * 进入指定阶段。重建炮台和 schedule。
     * 由构造函数和 BossStageSystem 调用。
     */
    public enterStage(index: number): void {
        const stage = this.config.stages[index];
        if (!stage) {
            console.warn(`[Boss] 阶段 ${index} 不存在`);
            return;
        }
        this.stageIndex = index;

        // 重建炮台
        this.turrets = stage.turrets.map(cfg => ({
            config: cfg,
            aimAngle: cfg.baseAngle,
            runtime: new EmitterRuntime(), 
            oscPhase: 0,
        }));

        // 重建 schedule
        if (stage.turretSchedule) {
            this.turretSchedule = {
                config: stage.turretSchedule,
                activeIndex: 0,
                burstElapsed: 0,
                gapTimer: 0,
            };
        } else {
            this.turretSchedule = null;
        }
    }
}


